// PostgREST returns a JSON array. n8n's HTTP Request node passes it through
// as a single item whose .json IS that array — normalize defensively either way.
function asRows(x) {
  if (Array.isArray(x)) return x;
  if (x && Array.isArray(x.data)) return x.data;
  return x ? [x] : [];
}

const rows = asRows($input.first().json);
const row = rows[0];

const BASE = "Good morning, Ms. Gonzales. Class is in session — today's 5x5. " +
  "Script: catch up first, then offer a free equity check. " +
  "Reply DONE tonight with your numbers.";

if (!row || !row.streak_end || !row.days) {
  return [{ json: { message: BASE } }];
}

const today = new Date();
today.setHours(0, 0, 0, 0);
const dow = today.getDay(); // 0=Sun ... 1=Mon ... 5=Fri
const lastBusinessDay = new Date(today);
lastBusinessDay.setDate(today.getDate() - (dow === 1 ? 3 : 1)); // Monday -> back to Friday

const streakEnd = new Date(row.streak_end + 'T00:00:00');
const isAlive = streakEnd.getTime() === lastBusinessDay.getTime();

const message = isAlive
  ? `${BASE} You're on a ${row.days}-day streak — don't break the chain.`
  : BASE;

return [{ json: { message } }];
